// charsets -- the single-byte character sets of formats::encoding (generated by tools/gen_encodings.py,
// do not edit): the WHATWG Encoding Standard's single-byte encodings and labels, the DOS code pages of old
// files.  Tables: bytes 0x80..0xFF -> Unicode, 0 unassigned (below 0x80 every set is ASCII).  The labels and
// the standard's tables: Copyright © WHATWG (Apple, Google, Mozilla, Microsoft), BSD 3-Clause License
// (licenses/WHATWG-LICENSE.txt).

use crate::encoding::{Label, MultiByte};

/// a single-byte character set: the bytes below 0x80 are ASCII, the others come from its table.
/// The single-byte encodings of the WHATWG Encoding Standard (what browsers, HTML and mail use; `whatwg()`)
/// and the DOS code pages of old files (by `from_code_page` or by name here; no web label names them)
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[non_exhaustive]
pub enum Charset {
    /// IBM866: DOS Cyrillic
    Ibm866,
    /// ISO-8859-2: Latin 2, Central European
    Iso8859_2,
    /// ISO-8859-3: Latin 3, South European
    Iso8859_3,
    /// ISO-8859-4: Latin 4, North European
    Iso8859_4,
    /// ISO-8859-5: Cyrillic
    Iso8859_5,
    /// ISO-8859-6: Arabic
    Iso8859_6,
    /// ISO-8859-7: Greek
    Iso8859_7,
    /// ISO-8859-8: Hebrew, visual order
    Iso8859_8,
    /// ISO-8859-8-I: Hebrew, logical order (the same bytes as ISO-8859-8)
    Iso8859_8I,
    /// ISO-8859-10: Latin 6, Nordic
    Iso8859_10,
    /// ISO-8859-13: Latin 7, Baltic
    Iso8859_13,
    /// ISO-8859-14: Latin 8, Celtic
    Iso8859_14,
    /// ISO-8859-15: Latin 9, Latin 1 with the euro sign
    Iso8859_15,
    /// ISO-8859-16: Latin 10, South-Eastern European
    Iso8859_16,
    /// KOI8-R: Russian
    Koi8R,
    /// KOI8-U: Ukrainian and Belarusian (WHATWG's KOI8-RU)
    Koi8U,
    /// macintosh: Mac OS Roman
    Macintosh,
    /// windows-874: Thai (also TIS-620 and ISO-8859-11)
    Windows874,
    /// windows-1250: Windows Central European
    Windows1250,
    /// windows-1251: Windows Cyrillic
    Windows1251,
    /// windows-1252: Windows Western (also ISO-8859-1 and ASCII on the web)
    Windows1252,
    /// windows-1253: Windows Greek
    Windows1253,
    /// windows-1254: Windows Turkish (also ISO-8859-9)
    Windows1254,
    /// windows-1255: Windows Hebrew
    Windows1255,
    /// windows-1256: Windows Arabic
    Windows1256,
    /// windows-1257: Windows Baltic
    Windows1257,
    /// windows-1258: Windows Vietnamese
    Windows1258,
    /// x-mac-cyrillic: Mac OS Cyrillic
    XMacCyrillic,
    /// x-user-defined: bytes 0x80..0xFF as U+F780..U+F7FF (WHATWG)
    XUserDefined,
    /// ISO-8859-1: ISO-8859-1 exactly: each byte is its code point (the web reads the label as windows-1252) (not WHATWG)
    Latin1,
    /// IBM437: DOS United States (also ZIP names without the UTF-8 flag) (not WHATWG)
    Ibm437,
    /// IBM737: DOS Greek (not WHATWG)
    Ibm737,
    /// IBM775: DOS Baltic (not WHATWG)
    Ibm775,
    /// IBM850: DOS Western European (not WHATWG)
    Ibm850,
    /// IBM852: DOS Central European (not WHATWG)
    Ibm852,
    /// IBM855: DOS Cyrillic (IBM) (not WHATWG)
    Ibm855,
    /// IBM857: DOS Turkish (not WHATWG)
    Ibm857,
    /// IBM00858: DOS Western European with the euro sign (not WHATWG)
    Ibm858,
    /// IBM860: DOS Portuguese (not WHATWG)
    Ibm860,
    /// IBM861: DOS Icelandic (not WHATWG)
    Ibm861,
    /// IBM862: DOS Hebrew (not WHATWG)
    Ibm862,
    /// IBM863: DOS Canadian French (not WHATWG)
    Ibm863,
    /// IBM864: DOS Arabic (not WHATWG)
    Ibm864,
    /// IBM865: DOS Nordic (not WHATWG)
    Ibm865,
    /// IBM869: DOS Greek 2 (not WHATWG)
    Ibm869,
}

