    /// whether it is one of the WHATWG Encoding Standard's encodings (the others have no web label)
    pub const fn whatwg(self) -> bool {
        match self {
            Charset::Ibm866 | Charset::Iso8859_2 | Charset::Iso8859_3 | Charset::Iso8859_4 | Charset::Iso8859_5 | Charset::Iso8859_6 | Charset::Iso8859_7 | Charset::Iso8859_8 | Charset::Iso8859_8I | Charset::Iso8859_10 | Charset::Iso8859_13 | Charset::Iso8859_14 | Charset::Iso8859_15 | Charset::Iso8859_16 | Charset::Koi8R | Charset::Koi8U | Charset::Macintosh | Charset::Windows874 | Charset::Windows1250 | Charset::Windows1251 | Charset::Windows1252 | Charset::Windows1253 | Charset::Windows1254 | Charset::Windows1255 | Charset::Windows1256 | Charset::Windows1257 | Charset::Windows1258 | Charset::XMacCyrillic | Charset::XUserDefined => true,
            _ => false,
        }
    }

