// a label of the WHATWG Encoding Standard, already without whitespace and in lower case -> what it names
pub(crate) fn lookup(label: &str) -> Option<Label> {
    Some(match label {
        "unicode-1-1-utf-8" | "unicode11utf8" | "unicode20utf8" | "utf-8" | "utf8" | "x-unicode20utf8" => Label::Utf8,
        "866" | "cp866" | "csibm866" | "ibm866" => Label::Single(Charset::Ibm866),
        "csisolatin2" | "iso-8859-2" | "iso-ir-101" | "iso8859-2" | "iso88592" | "iso_8859-2" | "iso_8859-2:1987" | "l2" | "latin2" => Label::Single(Charset::Iso8859_2),
        "csisolatin3" | "iso-8859-3" | "iso-ir-109" | "iso8859-3" | "iso88593" | "iso_8859-3" | "iso_8859-3:1988" | "l3" | "latin3" => Label::Single(Charset::Iso8859_3),
        "csisolatin4" | "iso-8859-4" | "iso-ir-110" | "iso8859-4" | "iso88594" | "iso_8859-4" | "iso_8859-4:1988" | "l4" | "latin4" => Label::Single(Charset::Iso8859_4),
        "csisolatincyrillic" | "cyrillic" | "iso-8859-5" | "iso-ir-144" | "iso8859-5" | "iso88595" | "iso_8859-5" | "iso_8859-5:1988" => Label::Single(Charset::Iso8859_5),
        "arabic" | "asmo-708" | "csiso88596e" | "csiso88596i" | "csisolatinarabic" | "ecma-114" | "iso-8859-6" | "iso-8859-6-e" | "iso-8859-6-i" | "iso-ir-127" | "iso8859-6" | "iso88596" | "iso_8859-6" | "iso_8859-6:1987" => Label::Single(Charset::Iso8859_6),
        "csisolatingreek" | "ecma-118" | "elot_928" | "greek" | "greek8" | "iso-8859-7" | "iso-ir-126" | "iso8859-7" | "iso88597" | "iso_8859-7" | "iso_8859-7:1987" | "sun_eu_greek" => Label::Single(Charset::Iso8859_7),
        "csiso88598e" | "csisolatinhebrew" | "hebrew" | "iso-8859-8" | "iso-8859-8-e" | "iso-ir-138" | "iso8859-8" | "iso88598" | "iso_8859-8" | "iso_8859-8:1988" | "visual" => Label::Single(Charset::Iso8859_8),
        "csiso88598i" | "iso-8859-8-i" | "logical" => Label::Single(Charset::Iso8859_8I),
        "csisolatin6" | "iso-8859-10" | "iso-ir-157" | "iso8859-10" | "iso885910" | "l6" | "latin6" => Label::Single(Charset::Iso8859_10),
        "iso-8859-13" | "iso8859-13" | "iso885913" => Label::Single(Charset::Iso8859_13),
        "iso-8859-14" | "iso8859-14" | "iso885914" => Label::Single(Charset::Iso8859_14),
        "csisolatin9" | "iso-8859-15" | "iso8859-15" | "iso885915" | "iso_8859-15" | "l9" => Label::Single(Charset::Iso8859_15),
        "iso-8859-16" => Label::Single(Charset::Iso8859_16),
        "cskoi8r" | "koi" | "koi8" | "koi8-r" | "koi8_r" => Label::Single(Charset::Koi8R),
        "koi8-ru" | "koi8-u" => Label::Single(Charset::Koi8U),
        "csmacintosh" | "mac" | "macintosh" | "x-mac-roman" => Label::Single(Charset::Macintosh),
        "dos-874" | "iso-8859-11" | "iso8859-11" | "iso885911" | "tis-620" | "windows-874" => Label::Single(Charset::Windows874),
        "cp1250" | "windows-1250" | "x-cp1250" => Label::Single(Charset::Windows1250),
        "cp1251" | "windows-1251" | "x-cp1251" => Label::Single(Charset::Windows1251),
        "ansi_x3.4-1968" | "ascii" | "cp1252" | "cp819" | "csisolatin1" | "ibm819" | "iso-8859-1" | "iso-ir-100" | "iso8859-1" | "iso88591" | "iso_8859-1" | "iso_8859-1:1987" | "l1" | "latin1" | "us-ascii" | "windows-1252" | "x-cp1252" => Label::Single(Charset::Windows1252),
        "cp1253" | "windows-1253" | "x-cp1253" => Label::Single(Charset::Windows1253),
        "cp1254" | "csisolatin5" | "iso-8859-9" | "iso-ir-148" | "iso8859-9" | "iso88599" | "iso_8859-9" | "iso_8859-9:1989" | "l5" | "latin5" | "windows-1254" | "x-cp1254" => Label::Single(Charset::Windows1254),
        "cp1255" | "windows-1255" | "x-cp1255" => Label::Single(Charset::Windows1255),
        "cp1256" | "windows-1256" | "x-cp1256" => Label::Single(Charset::Windows1256),
        "cp1257" | "windows-1257" | "x-cp1257" => Label::Single(Charset::Windows1257),
        "cp1258" | "windows-1258" | "x-cp1258" => Label::Single(Charset::Windows1258),
        "x-mac-cyrillic" | "x-mac-ukrainian" => Label::Single(Charset::XMacCyrillic),
        "x-user-defined" => Label::Single(Charset::XUserDefined),
        "chinese" | "csgb2312" | "csiso58gb231280" | "gb2312" | "gb_2312" | "gb_2312-80" | "gbk" | "iso-ir-58" | "x-gbk" => Label::Multi(MultiByte::Gbk),
        "gb18030" => Label::Multi(MultiByte::Gb18030),
        "big5" | "big5-hkscs" | "cn-big5" | "csbig5" | "x-x-big5" => Label::Multi(MultiByte::Big5),
        "cseucpkdfmtjapanese" | "euc-jp" | "x-euc-jp" => Label::Multi(MultiByte::EucJp),
        "csiso2022jp" | "iso-2022-jp" => Label::Multi(MultiByte::Iso2022Jp),
        "csshiftjis" | "ms932" | "ms_kanji" | "shift-jis" | "shift_jis" | "sjis" | "windows-31j" | "x-sjis" => Label::Multi(MultiByte::ShiftJis),
        "cseuckr" | "csksc56011987" | "euc-kr" | "iso-ir-149" | "korean" | "ks_c_5601-1987" | "ks_c_5601-1989" | "ksc5601" | "ksc_5601" | "windows-949" => Label::Multi(MultiByte::EucKr),
        "csiso2022kr" | "hz-gb-2312" | "iso-2022-cn" | "iso-2022-cn-ext" | "iso-2022-kr" | "replacement" => Label::Replacement,
        "unicodefffe" | "utf-16be" => Label::Utf16Be,
        "csunicode" | "iso-10646-ucs-2" | "ucs-2" | "unicode" | "unicodefeff" | "utf-16" | "utf-16le" => Label::Utf16Le,
        _ => return None,
    })
}

